import { computeShrinkTarget, effectiveTransitionDuration, nextExperienceState, resolvePreset } from "../transition-engine.js";
import { ambientCanvasSize, ambientCoverScale, resolvePresentation } from "../video-fit.js";
import { createHeightReporter } from "../flow-layout.js";

const els = Object.fromEntries(["experience","profile","introLayer","mediaStage","avatarTarget","introVideo","skipButton","previewStart","progressBar","previewAvatar","previewName","previewHandle","previewPrimaryRole","previewSecondaryRoles","previewEducation","previewBio","previewBadge","previewPrivate","previewEyebrow"].map(id => [id,document.getElementById(id)]));
const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)");
let state = "profile"; let token = 0; let transitionTimer; let splitArmed;

function setState(event){ state=nextExperienceState(state,event); els.experience.dataset.state=state; els.profile.setAttribute("aria-hidden",String(state!=="profile")); document.body.classList.toggle("is-experiencing",state!=="profile"); parent.postMessage({type:"gamid-intro-preview-state",state},location.origin); reportHeight(); }
function clearSplitVideos(){ els.mediaStage.querySelectorAll(".split-live-video").forEach(v=>{v.pause();v.removeAttribute("src");v.load();v.remove();}); }
function armSplitLiveVideo(sourceVideo){ clearSplitVideos(); const src=sourceVideo.currentSrc||sourceVideo.src; if(!src)return; const at=sourceVideo.currentTime; sourceVideo.pause(); els.mediaStage.querySelectorAll(".split-panel").forEach(panel=>{const clone=document.createElement("video");clone.className="split-live-video";clone.muted=true;clone.playsInline=true;clone.loop=true;clone.src=src;clone.dataset.fit=els.introVideo.dataset.fit||"contain";panel.appendChild(clone);clone.currentTime=at;clone.play().catch(()=>{});}); }
function finish(current){ if(current!==token)return; setState("TRANSITION_COMPLETE"); els.introLayer.style.visibility="hidden"; clearSplitVideos(); }
function begin(config,current){ if(current!==token||state!=="intro")return; if(splitArmed){els.introVideo.removeEventListener("timeupdate",splitArmed);splitArmed=null;} if(config.transitionKey==="split")armSplitLiveVideo(els.introVideo); if(config.transitionKey==="shrink"){els.profile.classList.add("measure-target");const target=computeShrinkTarget(els.introLayer.getBoundingClientRect(),els.avatarTarget.getBoundingClientRect());els.profile.classList.remove("measure-target");els.mediaStage.style.setProperty("--shrink-x",`${target.x}px`);els.mediaStage.style.setProperty("--shrink-y",`${target.y}px`);els.mediaStage.style.setProperty("--shrink-scale",target.scale);els.mediaStage.style.setProperty("--shrink-radius",`${target.clipRadius}px`);} setState("INTRO_COMPLETE");const duration=effectiveTransitionDuration(1400,reduceMotion.matches);els.experience.style.setProperty("--transition-ms",`${duration}ms`);transitionTimer=setTimeout(()=>finish(current),duration+60); }
function play(config){ document.documentElement.dataset.flow=config.publicMode===true?"on":"";syncParentViewport(); clearTimeout(transitionTimer); if(splitArmed){els.introVideo.removeEventListener("timeupdate",splitArmed);splitArmed=null;} clearSplitVideos(); token+=1;const current=token;els.previewAvatar.src=config.avatarUrl||"";els.previewName.textContent=config.displayName||"Gamer";els.previewHandle.textContent=config.handle||"@handle";els.previewPrimaryRole.textContent=config.primaryRole||"";els.previewSecondaryRoles.textContent=(config.secondaryRoles||[]).join(" · ");els.previewEducation.textContent=config.education||"";els.previewBio.textContent=config.bio||"";els.previewBadge.hidden=Boolean(config.publicMode);els.previewPrivate.hidden=Boolean(config.publicMode);els.previewEyebrow.hidden=Boolean(config.publicMode);if(!config.videoUrl){els.introVideo.removeAttribute("src");setState("SKIP");els.introLayer.style.visibility="hidden";return;}const preset=resolvePreset(config.transitionKey);els.introLayer.className=`intro-layer ${preset.className}`;els.experience.dataset.preset=config.transitionKey;els.introLayer.style.visibility="visible";els.introVideo.src=config.videoUrl;state="profile";setState("REPLAY");els.introVideo.currentTime=0;els.previewStart.hidden=true;const start=()=>els.introVideo.play().then(()=>{els.previewStart.hidden=true;}).catch(()=>{els.previewStart.hidden=false;});start();els.previewStart.onclick=start;els.introVideo.onended=()=>begin(config,current);els.introVideo.onerror=()=>parent.postMessage({type:"gamid-intro-preview-error"},location.origin);if(config.transitionKey==="split"&&!reduceMotion.matches){const threshold=effectiveTransitionDuration(1400,reduceMotion.matches)/1000;splitArmed=()=>{if(els.introVideo.duration&&els.introVideo.duration-els.introVideo.currentTime<=threshold)begin(config,current);};els.introVideo.addEventListener("timeupdate",splitArmed);} }
// Aspect-ratio-safe presentation: the video is never stretched (policy in ../video-fit.js).
//  * portrait sources: cover when little of the picture would be lost, otherwise contain (unchanged).
//  * landscape / square sources: the real video is a sharp, centered, aspect-correct FOREGROUND (contain, never cropped, never enlarged past MAX_UPSCALE device
//    pixels per source pixel) and the leftover stage is filled by an ambient glow taken from the SAME playing video (no second download, no second decoder).
const ambientCanvas=document.getElementById("introAmbient"),ambientCtx=ambientCanvas.getContext("2d",{alpha:false});
const ambient={on:false,w:0,h:0,last:0,handle:0,useFrameCallback:typeof HTMLVideoElement!=="undefined"&&"requestVideoFrameCallback" in HTMLVideoElement.prototype};
// One tiny drawImage (32 px wide) + a dark wash; the browser scales the canvas up smoothly. No pixel reads, no per-frame color analysis.
function drawAmbient(){const v=els.introVideo;if(!ambient.on||v.readyState<2)return;try{ambientCtx.imageSmoothingEnabled=true;ambientCtx.imageSmoothingQuality="high";ambientCtx.filter="saturate(1.35)";ambientCtx.drawImage(v,0,0,ambient.w,ambient.h);ambientCtx.filter="none";ambientCtx.fillStyle="rgba(4,3,9,.2)";ambientCtx.fillRect(0,0,ambient.w,ambient.h);}catch{/* a frame that cannot be drawn just keeps the previous glow */}}
function ambientTick(now){ambient.handle=0;if(!ambient.on||els.introLayer.style.visibility==="hidden")return;const gap=reduceMotion.matches?2000:90;if(!ambient.last||now-ambient.last>=gap){ambient.last=now||performance.now();drawAmbient();}queueAmbient();}
function queueAmbient(){if(!ambient.on||ambient.handle)return;const v=els.introVideo;if(ambient.useFrameCallback)ambient.handle=v.requestVideoFrameCallback(ambientTick);else if(!v.paused&&!v.ended)ambient.handle=requestAnimationFrame(ambientTick);}
function stopAmbient(){ambient.on=false;if(ambient.handle){if(ambient.useFrameCallback)els.introVideo.cancelVideoFrameCallback(ambient.handle);else cancelAnimationFrame(ambient.handle);ambient.handle=0;}}
function startAmbient(size,scale){if(ambient.w!==size.width||ambient.h!==size.height){ambient.w=ambientCanvas.width=size.width;ambient.h=ambientCanvas.height=size.height;}ambientCanvas.style.setProperty("--amb-k",String(scale));if(!ambient.on){ambient.on=true;ambient.last=0;}drawAmbient();queueAmbient();}
function applyVideoFit(){const v=els.introVideo;if(!v.videoWidth||!v.videoHeight)return;const stageW=els.mediaStage.clientWidth,stageH=els.mediaStage.clientHeight;const p=resolvePresentation(v.videoWidth,v.videoHeight,stageW,stageH,window.devicePixelRatio||1);v.dataset.fit=p.fit;els.experience.dataset.fit=p.fit;els.experience.dataset.orient=p.orientation;
  if(p.foreground){els.experience.style.setProperty("--fg-w",`${p.foreground.width}px`);els.experience.style.setProperty("--fg-h",`${p.foreground.height}px`);}else{els.experience.style.removeProperty("--fg-w");els.experience.style.removeProperty("--fg-h");}
  els.mediaStage.querySelectorAll(".split-live-video").forEach(clone=>{clone.dataset.fit=p.fit;});
  if(p.ambient){const size=ambientCanvasSize(v.videoWidth,v.videoHeight);startAmbient(size,ambientCoverScale(size.width,size.height,stageW,stageH));}else stopAmbient();}
els.introVideo.addEventListener("loadedmetadata",applyVideoFit);addEventListener("resize",applyVideoFit);
["loadeddata","seeked","play","playing"].forEach(name=>els.introVideo.addEventListener(name,()=>{if(ambient.on){drawAmbient();queueAmbient();}}));
els.skipButton.addEventListener("click",()=>{token+=1;clearTimeout(transitionTimer);if(splitArmed){els.introVideo.removeEventListener("timeupdate",splitArmed);splitArmed=null;}els.introVideo.pause();state="intro";setState("SKIP");els.introLayer.style.visibility="hidden";clearSplitVideos();});
let configReceived=false,readyAttempts=0,readyTimer;
const READY_RETRY_LIMIT=25,READY_RETRY_MS=200;
function announceReady(){if(configReceived){clearInterval(readyTimer);return;}if(readyAttempts>=READY_RETRY_LIMIT){clearInterval(readyTimer);return;}readyAttempts++;parent.postMessage({type:"gamid-intro-preview-ready"},location.origin);}
addEventListener("message",event=>{if(event.origin!==location.origin||event.data?.type!=="gamid-intro-preview")return;configReceived=true;clearInterval(readyTimer);play(event.data.config);});
announceReady();
readyTimer=setInterval(announceReady,READY_RETRY_MS);
// PUBLIC FLOW HEIGHT. On the public page (config.publicMode) the profile is ordinary document content once the Intro is over: the host page gives this frame exactly the
// height reported here and the PAGE scrolls, so nothing in the profile has a viewport-based height (see the html[data-flow="on"] rules in intro-preview.css).
// The height is measured on the profile's own block, which is content-sized in that mode, so it can never depend on the frame's current height (no resize loop). It is
// reported after the state changes, whenever the block resizes (text wrapping, fonts, content) and after a resize; an unchanged value is never re-sent.
// Owner previews (no publicMode) never report anything and keep their exact behavior.
const flowShell=document.querySelector(".prototype-shell");
function flowActive(){return document.documentElement.dataset.flow==="on"&&!document.body.classList.contains("is-experiencing");}
function syncParentViewport(){try{document.documentElement.style.setProperty("--pvh",`${(parent.innerHeight||innerHeight)/100}px`);}catch{/* a host we cannot read keeps the 1vh fallback */}}
const reportHeight=createHeightReporter({active:flowActive,measure:()=>flowShell.getBoundingClientRect().height,post:height=>parent.postMessage({type:"gamid-intro-preview-height",height},location.origin)});
if(typeof ResizeObserver!=="undefined")new ResizeObserver(reportHeight).observe(flowShell);
addEventListener("message",event=>{if(event.origin===location.origin&&event.data?.type==="gamid-intro-preview-measure")reportHeight();});   // the host asks after it reveals this frame (a hidden frame measures 0)
document.fonts?.ready?.then(reportHeight);
addEventListener("resize",()=>{syncParentViewport();reportHeight();});
